# Single message fetch + image download (for quote/reply context)
# ---------------------------------------------------------------------------


def get_message(message_id: str) -> ToolResult:
    """Fetch a single message by message_id via Feishu API.

    Returns msg_type, content_text, content_raw, sender_id.
    """
    try:
        from lark_oapi.api.im.v1 import GetMessageRequest

        client = _get_client()
        request = GetMessageRequest.builder().message_id(message_id).build()
        response = client.im.v1.message.get(request)

        if not response.success():
            return ToolResult(
                success=False,
                error=f"get_message failed: {response.code} - {response.msg}",
            )

        items = getattr(response.data, "items", None) or []
        if not items:
            return ToolResult(success=False, error=f"Message {message_id} not found")

        item = items[0]
        content_dict: dict = {}
        try:
            content_dict = json.loads(item.body.content) if item.body else {}
        except (json.JSONDecodeError, AttributeError):
            pass

        msg_type = getattr(item, "msg_type", "text") or "text"

        if msg_type == "text":
            text = content_dict.get("text", "")
        elif msg_type == "post":
            text = _extract_post_text(content_dict)
        elif msg_type == "image":
            text = ""
        elif msg_type == "file":
            text = content_dict.get("file_name", "")
        else:
            text = str(content_dict)

        return ToolResult(
            success=True,
            data={
                "message_id": item.message_id,
                "msg_type": msg_type,
                "content_text": text,
                "content_raw": content_dict,
                "sender_id": getattr(item.sender, "id", "") if item.sender else "",
            },
        )
    except ImportError as e:
        return ToolResult(success=False, error=str(e))
    except Exception as e:
        logger.exception("Failed to get message %s", message_id)
        return ToolResult(success=False, error=f"get_message failed: {e}")


def download_message_image(message_id: str, image_key: str) -> tuple[bytes, str] | None:
    """Download an image resource from a Feishu message.

    Returns (image_bytes, mime_type) or None on failure.
    """
    try:
        from lark_oapi.api.im.v1 import GetMessageResourceRequest

        client = _get_client()
        request = (
            GetMessageResourceRequest.builder()
            .message_id(message_id)
            .file_key(image_key)
            .type("image")
            .build()
        )
        response = client.im.v1.message_resource.get(request)

        if response.code != 0 or not response.file:
            logger.warning(
                "Failed to download image %s from message %s: code=%s",
                image_key, message_id, response.code,
            )
            return None

        image_bytes = response.file.read()
        if not image_bytes:
            return None

        # Size guard — skip images > 10 MB (Anthropic limit ~20 MB)
        if len(image_bytes) > 10 * 1024 * 1024:
            logger.warning("Image too large (%d bytes), skipping", len(image_bytes))
            return None

        file_name = getattr(response, "file_name", "") or ""
        if file_name.endswith((".jpg", ".jpeg")):
            mime_type = "image/jpeg"
        elif file_name.endswith(".gif"):
            mime_type = "image/gif"
        elif file_name.endswith(".webp"):
            mime_type = "image/webp"
        else:
            mime_type = "image/png"

        return image_bytes, mime_type

    except Exception as e:
        logger.exception("Failed to download image %s from %s", image_key, message_id)
        return None


def download_message_file(message_id: str, file_key: str) -> tuple[bytes, str] | None:
    """Download a file resource from a Feishu message.

    Returns (file_bytes, file_name) or None on failure.
    """
    try:
        from lark_oapi.api.im.v1 import GetMessageResourceRequest

        client = _get_client()
        request = (
            GetMessageResourceRequest.builder()
            .message_id(message_id)
            .file_key(file_key)
            .type("file")
            .build()
        )

